package bowling

import "errors"

var (
	errNegativeRoll = errors.New("Negative roll is invalid")
	errTooManyPins  = errors.New("Pin count exceeds pins on the lane")
	errGameOver     = errors.New("Cannot roll after game is over")
	errIncomplete   = errors.New("Score cannot be taken until the end of the game")
)

// Game keeps track of the rolls in a bowling game.
type Game struct {
	rolls       []int // every roll, in order
	frame       int   // current frame index, 0-based; 10 means the game is over
	rollInFrame int   // number of rolls taken in the current frame
}

// NewGame returns a new, empty Game.
func NewGame() *Game {
	return &Game{}
}

// gameOver reports whether all ten frames have been completed.
func (g *Game) gameOver() bool {
	return g.frame > 9
}

// Roll records a throw of the ball, validating it against the rules.
func (g *Game) Roll(pins int) error {
	if pins < 0 {
		return errNegativeRoll
	}
	if pins > 10 {
		return errTooManyPins
	}
	if g.gameOver() {
		return errGameOver
	}

	if g.frame < 9 {
		if g.rollInFrame == 1 {
			// Second roll of the frame: cannot exceed the pins still standing.
			if pins > 10-g.rolls[len(g.rolls)-1] {
				return errTooManyPins
			}
		}
	} else {
		// Tenth frame, with its special bonus-roll rules.
		switch g.rollInFrame {
		case 1:
			first := g.rolls[len(g.rolls)-1]
			if first != 10 && pins > 10-first {
				return errTooManyPins
			}
		case 2:
			first := g.rolls[len(g.rolls)-2]
			second := g.rolls[len(g.rolls)-1]
			if first == 10 && second != 10 && pins > 10-second {
				return errTooManyPins
			}
		}
	}

	g.rolls = append(g.rolls, pins)

	if g.frame < 9 {
		if g.rollInFrame == 0 && pins == 10 {
			g.frame++ // strike ends the frame
		} else if g.rollInFrame == 0 {
			g.rollInFrame = 1
		} else {
			g.frame++ // second roll ends the frame
		}
	} else {
		// Tenth frame: a strike or spare earns a bonus roll.
		if g.rollInFrame == 0 {
			g.rollInFrame = 1
		} else if g.rollInFrame == 1 {
			first := g.rolls[len(g.rolls)-2]
			if first == 10 || first+pins == 10 {
				g.rollInFrame = 2
			} else {
				g.frame = 10 // open tenth frame ends the game
			}
		} else {
			g.frame = 10 // bonus roll ends the game
		}
	}

	return nil
}

// Score returns the total score once the game is complete.
func (g *Game) Score() (int, error) {
	if !g.gameOver() {
		return 0, errIncomplete
	}

	total := 0
	i := 0
	for frame := 0; frame < 10; frame++ {
		switch {
		case g.rolls[i] == 10:
			total += 10 + g.rolls[i+1] + g.rolls[i+2]
			i++
		case g.rolls[i]+g.rolls[i+1] == 10:
			total += 10 + g.rolls[i+2]
			i += 2
		default:
			total += g.rolls[i] + g.rolls[i+1]
			i += 2
		}
	}
	return total, nil
}

